import { useEffect, useRef, useState } from "react";

export type MenuItem = {
  id: string;
  label: string;
  shortcut?: string;
  checked?: boolean;
  disabled?: boolean;
};

export type MenuGroup = { title: string; items: MenuItem[] };

export function CommandMenuPopover({
  label = "Actions",
  groups,
  onRun,
}: {
  label?: string;
  groups: MenuGroup[];
  onRun: (id: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  return (
    <div className="cmp-root" ref={rootRef}>
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        className="cmp-trigger"
      >
        {label}
        <span aria-hidden="true">⌄</span>
      </button>

      {open ? (
        <div className="cmp-menu" role="menu">
          {groups.map((group) => (
            <div key={group.title} className="cmp-group">
              <p className="cmp-group-title">{group.title}</p>
              {group.items.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  role="menuitemcheckbox"
                  aria-checked={Boolean(item.checked)}
                  disabled={item.disabled}
                  onClick={() => {
                    if (item.disabled) return;
                    onRun(item.id);
                    setOpen(false);
                  }}
                  className="cmp-item"
                >
                  <span className="cmp-check" aria-hidden="true">
                    {item.checked ? "✓" : ""}
                  </span>
                  <span className="cmp-label">{item.label}</span>
                  {item.shortcut ? (
                    <kbd className="cmp-shortcut">{item.shortcut}</kbd>
                  ) : null}
                </button>
              ))}
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
}

