.cmp-root {
  position: relative;
  display: inline-block;
  font-size: 13px;
}
.cmp-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  font: inherit;
  border-radius: 7px;
  border: 1px solid var(--line-subtle, #e4e4e7);
  background: var(--surface-base, #ffffff);
  color: var(--text-strong, #18181b);
  cursor: pointer;
}
.cmp-trigger:hover {
  background: var(--surface-inset, #f4f4f5);
}
.cmp-trigger:focus-visible {
  outline: 2px solid var(--accent, #4f46e5);
  outline-offset: 2px;
}
.cmp-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 20;
  min-width: 216px;
  padding: 5px;
  border-radius: 10px;
  background: var(--surface-overlay, #ffffff);
  border: 1px solid var(--line-subtle, #e4e4e7);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.16);
}
.cmp-group + .cmp-group {
  padding-top: 5px;
  border-top: 1px solid var(--line-subtle, #f1f1f3);
  margin-top: 5px;
}
.cmp-group-title {
  margin: 0 0 3px;
  padding: 3px 9px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted, #a1a1aa);
}
.cmp-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 9px;
  font: inherit;
  text-align: left;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.cmp-item:hover:not(:disabled) {
  background: var(--accent-soft, rgba(79, 70, 229, 0.1));
}
.cmp-item:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.cmp-check {
  width: 12px;
  font-size: 11px;
}
.cmp-label {
  flex: 1;
}
.cmp-shortcut {
  font-family: ui-monospace, monospace;
  font-size: 10px;
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--surface-inset, #f4f4f5);
  color: var(--text-muted, #71717a);
}
